def collect(item, items=None):
    if items is None:
        items = []
    items.append(item)
    return items

def calc(first, second, third):
    return first + 2 * second + 3 * third

print(calc(third=4, second=2, first=3))  # 19

def multiply(*args, factor=2):
    total = 1
    for num in args:
        total *= num
    return total * factor

def collect(first, *args, scale=1, **kwargs):
    return first * scale, args, kwargs

result, extras, options = collect(2, 3, 4, scale=10, unit='cm')
print(result)   # 20
print(extras)   # (3, 4)
print(options)  # {'unit': 'cm'}

def function_factory(increment):
    def adder(n1):
        return n1 + increment
    return adder

add4 = function_factory(4)
print(add4(3))  # 7
